int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    SSH_SESSION *session = (SSH_SESSION *)ctxt;
    KEX *kex = session->kex;

    if (!kex) {
        return SSH_ERR_NO_KEX;
    }

    /* Setup dispatch for key exchange initialization message */
    ssh_dispatch_set(session, SSH_MSG_KEXINIT, NULL);

    PACKET *pkt = packet_get();
    if (!pkt) {
        return SSH_ERR_ALLOC_FAIL;
    }

    /* Process the incoming packet */
    if (packet_read(pkt) != 0) {
        packet_free(pkt);
        return SSH_ERR_PACKET_RECV_FAILURE;
    }

    /* Discard unnecessary data from the packet */
    packet_discard(pkt);

    if (!session->kex_follows) {
        /* Send key exchange initialization message */
        if (kex_send_init(session) != 0) {
            packet_free(pkt);
            return SSH_ERR_KEX_INIT_SEND_FAILURE;
        }
    }

    /* Select appropriate key exchange method and execute it */
    if (kex_method_select(kex) != 0) {
        packet_free(pkt);
        return SSH_ERR_KEX_METHOD_SELECT_FAILURE;
    }

    if (kex->method->kex(kex) != 0) {
        packet_free(pkt);
        return SSH_ERR_KEX_EXECUTION_FAILURE;
    }

    packet_free(pkt);
    return 0;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    if (!ctxt) {
        return -1;  // Invalid context
    }

    // Setup SSH dispatch for key exchange initialization
    if (ssh_dispatch_set(ctxt, type, &kex_init_handler) != 0) {
        return -1;
    }

    Packet *pkt = packet_get(ctxt);
    if (!pkt) {
        return -1;  // Failed to get packet
    }

    // Discard unnecessary data from the packet
    packet_discard(pkt);

    // Check for the first key exchange follows flag
    int first_follows = packet_get_int(pkt);
    if (first_follows < 0) {
        return -1;  // Invalid flag value
    }

    if (!first_follows) {
        // Send key exchange initialization message if not already sent
        if (send_kex_init_message(ctxt) != 0) {
            return -1;
        }
    }

    // Select appropriate key exchange method and execute it
    const char *kex_method = select_kex_method(pkt);
    if (!kex_method) {
        return -1;  // No valid key exchange method found
    }

    if (execute_kex_method(ctxt, kex_method) != 0) {
        return -1;
    }

    return 0;  // Success
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    SSH_SESSION *session = (SSH_SESSION *)ctxt;
    if (!session || !session->kex) {
        return SSH_ERR_KEX_FAILURE;
    }

    if (ssh_dispatch_run(SSH_KEX_INIT_MSG, session->packet, session->dispatch, NULL) != 0) {
        return SSH_ERR_DISPATCH_FAILURE;
    }

    if (session->packet->len > 0) {
        sshpkt_discard(session->packet, session->packet->len);
    }

    if (!session->kex_initialized) {
        if (ssh_kex_send_init(session) != 0) {
            return SSH_ERR_KEX_FAILURE;
        }
        session->kex_initialized = 1;
    }

    if (session->kex->first_kex_follows) {
        if (ssh_kex_choose_method(session->kex, session->supported_kex_methods) != 0) {
            return SSH_ERR_UNSUPPORTED_KEX_METHOD;
        }
        if (ssh_kex_execute(session->kex, session->packet) != 0) {
            return SSH_ERR_KEX_FAILURE;
        }
    }

    return SSH_OK;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    ssh_session *session = ctxt;
    packet *pkt;

    if (!session || !session->kex) {
        return SSH_ERR_INVALID_ARGUMENT;
    }

    if ((pkt = sshpkt_get_end()) == NULL) {
        return SSH_ERR_ALLOC_FAIL;
    }

    if (pkt->len > 0) {
        packet_discard(pkt);
    }

    if (!session->kex->first_kex_follows) {
        if (kex_send_kexinit(session) != 0) {
            return SSH_ERR_SEND_KEXINIT_FAILED;
        }
    }

    if (kex_select_method(session) != 0) {
        return SSH_ERR_KEX_SELECT_FAILED;
    }

    return 0;
}
